const tea = new Product('чай', 250);
const honey = new Product('мёд', 400);

document.body.append(tea.label() + ' | ' + honey.label());

class Product {
  constructor(name, price) {
    this.name = name;
    this.price = price;
  }

  label() {
    return this.name + ': ' + this.price + ' руб.';
  }
}

class DiscountedProduct extends Product {
  constructor(name, price, percent) {
    super(name, price);   // сначала поля родителя, потом свои
    this.percent = percent;
  }

  finalPrice() {
    return this.price - (this.price * this.percent) / 100;
  }
}

const sale = new DiscountedProduct('кофе', 700, 15);
document.body.append(sale.label() + ' -> ' + sale.finalPrice() + ' руб.');

class Button {
  constructor(title) {
    this.title = title;
  }

  log() {
    return 'нажата ' + this.title;
  }
}

const ok = new Button('OK');
const detached = ok.log; // передали функцию без объекта

let result;
try {
  result = detached();
} catch (error) {
  result = error.message; // TypeError — this стал undefined
}

document.body.append(ok.log() + ' против ' + result);

